package cn.zhuatech.inspection.controller;import cn.zhuatech.inspection.common.ApiResponse;import cn.zhuatech.inspection.service.InspectionCoreService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController public class InspectionCoreController{private final InspectionCoreService service;public InspectionCoreController(InspectionCoreService service){this.service=service;}
 @PostMapping("/api/core/inspection/tasks")ApiResponse<InspectionCoreService.InspectionTask>create(@Valid@RequestBody InspectionCoreService.CreateTaskRequest r){return ApiResponse.ok(service.createTask(r));}@GetMapping("/api/core/inspection/tasks")ApiResponse<List<InspectionCoreService.InspectionTask>>tasks(@RequestParam(required=false)String status){return ApiResponse.ok(service.tasks(status));}@PostMapping("/api/core/inspection/tasks/{id}/start")ApiResponse<InspectionCoreService.InspectionTask>start(@PathVariable Long id){return ApiResponse.ok(service.start(id));}@PostMapping("/api/core/inspection/tasks/{id}/points")ApiResponse<InspectionCoreService.PointResult>point(@PathVariable Long id,@Valid@RequestBody InspectionCoreService.PointRequest r){return ApiResponse.ok(service.recordPoint(id,r));}@GetMapping("/api/core/inspection/tasks/{id}/points")ApiResponse<List<InspectionCoreService.PointResult>>points(@PathVariable Long id){return ApiResponse.ok(service.points(id));}@PostMapping("/api/core/inspection/tasks/{id}/hazards")ApiResponse<InspectionCoreService.Hazard>hazard(@PathVariable Long id,@Valid@RequestBody InspectionCoreService.HazardRequest r){return ApiResponse.ok(service.createHazard(id,r));}@GetMapping("/api/core/inspection/tasks/{id}/hazards")ApiResponse<List<InspectionCoreService.Hazard>>hazards(@PathVariable Long id){return ApiResponse.ok(service.hazards(id));}@PostMapping("/api/core/inspection/hazards/{id}/contain")ApiResponse<InspectionCoreService.Hazard>contain(@PathVariable Long id,@Valid@RequestBody InspectionCoreService.ActionRequest r){return ApiResponse.ok(service.contain(id,r));}@PostMapping("/api/core/inspection/hazards/{id}/rectify")ApiResponse<InspectionCoreService.Hazard>rectify(@PathVariable Long id,@Valid@RequestBody InspectionCoreService.RectifyRequest r){return ApiResponse.ok(service.rectify(id,r));}@PostMapping("/api/admin/core/inspection/hazards/{id}/verify")ApiResponse<InspectionCoreService.Hazard>verify(@PathVariable Long id,@Valid@RequestBody InspectionCoreService.VerifyRequest r){return ApiResponse.ok(service.verify(id,r));}@PostMapping("/api/admin/core/inspection/tasks/{id}/close")ApiResponse<InspectionCoreService.InspectionTask>close(@PathVariable Long id){return ApiResponse.ok(service.close(id));}@GetMapping("/api/core/inspection/summary")ApiResponse<InspectionCoreService.InspectionSummary>summary(){return ApiResponse.ok(service.summary());}}
